    if start == goal:
        return [start]

    visited = set()
    path = []

    def dfs(r, c, path_so_far):
        if (r, c) == goal:
            path_so_far.append((r, c))
            return True
        visited.add((r, c))
        path_so_far.append((r, c))
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
