from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Bidirectional BFS
    frontier_start = deque([start])
    frontier_goal = deque([goal])
    visited_start = {start: [start]}
    visited_goal = {goal: [goal]}

    while frontier_start and frontier_goal:
        # Expand from start
        for _ in range(len(frontier_start)):
            current = frontier_start.popleft()
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if is_valid(r, c):
                    if (r, c) not in visited_start:
                        visited_start[(r, c)] = visited_start[current] + [(r, c)]
                        if (r, c) in visited_goal:
                            return visited_start[(r, c)] + visited_goal[(r, c)][::-1][1:]
                        frontier_start.append((r, c))
        # Expand from goal
        for _ in range(len(frontier_goal)):
            current = frontier_goal.popleft()
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if is_valid(r, c):
                    if (r, c) not in visited_goal:
                        visited_goal[(r, c)] = visited_goal[current] + [(r, c)]
                        if (r, c) in visited_start:
                            return visited_start[(r, c)] + visited_goal[(r, c)][::-1][1:]
                        frontier_goal.append((r, c))

    return []
