from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or \
       not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def bfs(start, goal, visited):
        queue = deque([(start, [start])])
        visited.add(start)
        while queue:
            current, path = queue.popleft()
            if current == goal:
                return path
            for neighbor in get_neighbors(*current):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))
        return []

    visited_start = set()
    visited_goal = set()
    queue_start = deque([start])
    queue_goal = deque([goal])
    visited_start.add(start)
    visited_goal.add(goal)

    while queue_start and queue_goal:
        # Expand from start
        if len(queue_start) <= len(queue_goal):
            current, path = queue_start.popleft()
            for neighbor in get_neighbors(*current):
                if neighbor not in visited_start:
                    visited_start.add(neighbor)
                    queue_start.append(neighbor)
                    if neighbor in visited_goal:
                        return path + [neighbor]
        else:
            current, path = queue_goal.popleft()
            for neighbor in get_neighbors(*current):
                if neighbor not in visited_goal:
                    visited_goal.add(neighbor)
                    queue_goal.append(neighbor)
                    if neighbor in visited_start:
                        return path + [neighbor]

    return []
