from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start, goal, visited, other_visited, path):
        queue = deque([(start, [start])])
        visited.add(start)
        while queue:
            current, path = queue.popleft()
            if current in other_visited:
                return path + other_visited[current]
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.' and (r, c) not in visited:
                    visited.add((r, c))
                    queue.append(((r, c), path + [(r, c)]))
        return []

    start_visited = set()
    goal_visited = set()
    start_queue = deque([(start, [start])])
    goal_queue = deque([(goal, [goal])])
    start_visited.add(start)
    goal_visited.add(goal)

    while start_queue and goal_queue:
        result = bfs(start, goal, start_visited, goal_visited, [])
        if result:
            return result
        result = bfs(goal, start, goal_visited, start_visited, [])
        if result:
            return result
        if start_queue:
            current, path = start_queue.popleft()
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.' and (r, c) not in start_visited:
                    start_visited.add((r, c))
                    start_queue.append(((r, c), path + [(r, c)]))
        if goal_queue:
            current, path = goal_queue.popleft()
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.' and (r, c) not in goal_visited:
                    goal_visited.add((r, c))
                    goal_queue.append(((r, c), path + [(r, c)]))

    return []
