from collections import deque

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(start, goal):
        visited = set()
        queue = deque([(start[0], start[1], [start])])
        visited.add((start[0], start[1]))
        while queue:
            r, c, path = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    if (nr, nc) == goal:
                        return path + [(nr, nc)]
                    visited.add((nr, nc))
                    queue.append((nr, nc, path + [(nr, nc)]))
        return []

    forward = bfs(start, goal)
    if forward:
        return forward

    reverse_start = goal
    reverse_goal = start
    reverse_visited = set()
    reverse_visited.add((reverse_start[0], reverse_start[1]))
    reverse_queue = deque([(reverse_start[0], reverse_start[1], [reverse_start])])

    while reverse_queue:
        r, c, path = reverse_queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in reverse_visited:
                if (nr, nc) == reverse_goal:
                    return path + [(nr, nc)]
                reverse_visited.add((nr, nc))
                reverse_queue.append((nr, nc, path + [(nr, nc)]))

    return []
