from collections import deque

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if (start_row < 0 or start_row >= rows or start_col < 0 or start_col >= cols or
        grid[start_row][start_col] == '#' or
        grid[goal_row][goal_col] == '#'):
        return []

    if start == goal:
        return [start]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Bidirectional BFS
    def bfs(frontier, visited, other_visited):
        while frontier:
            r, c, path = frontier.popleft()
            if (r, c) in other_visited:
                return path + other_visited[(r, c)][1:]
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited[(nr, nc)] = path + [(nr, nc)]
                    frontier.append((nr, nc, visited[(nr, nc)]))

    # Initialize bidirectional BFS
    start_visited = {(start_row, start_col): [start]}
    goal_visited = {(goal_row, goal_col): [goal]}
    start_queue = deque()
    start_queue.append((start_row, start_col, [start]))
    goal_queue = deque()
    goal_queue.append((goal_row, goal_col, [goal]))

    while start_queue and goal_queue:
        result = bfs(start_queue, start_visited, goal_visited)
        if result:
            return result
        result = bfs(goal_queue, goal_visited, start_visited)
        if result:
            return result
    return []
