from collections import deque

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Bidirectional BFS
    forward_visited = {start: [start]}
    backward_visited = {goal: [goal]}
    forward_queue = deque([start])
    backward_queue = deque([goal])

    while forward_queue and backward_queue:
        # Expand forward direction
        if forward_queue:
            current = forward_queue.popleft()
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if is_valid(r, c) and (r, c) not in forward_visited:
                    forward_visited[(r, c)] = forward_visited[current] + [(r, c)]
                    forward_queue.append((r, c))
                    if (r, c) in backward_visited:
                        return forward_visited[(r, c)] + backward_visited[(r, c)][::-1]

        # Expand backward direction
        if backward_queue:
            current = backward_queue.popleft()
            for dr, dc in directions:
                r, c = current[0] + dr, current[1] + dc
                if is_valid(r, c) and (r, c) not in backward_visited:
                    backward_visited[(r, c)] = backward_visited[current] + [(r, c)]
                    backward_queue.append((r, c))
                    if (r, c) in forward_visited:
                        return forward_visited[(r, c)] + backward_visited[(r, c)][::-1]

    return []
