from collections import deque

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(queue, visited, parent):
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = (r, c)
                    queue.append((nr, nc))
                    if (nr, nc) == goal:
                        return True
        return False

    start_r, start_c = start
    goal_r, goal_c = goal

    if not is_valid(start_r, start_c) or not is_valid(goal_r, goal_c):
        return []

    forward_queue = deque([(start_r, start_c)])
    forward_visited = {(start_r, start_c)}
    forward_parent = {}

    backward_queue = deque([(goal_r, goal_c)])
    backward_visited = {(goal_r, goal_c)}
    backward_parent = {}

    while forward_queue and backward_queue:
        if bfs(forward_queue, forward_visited, forward_parent):
            path = [goal]
            current = goal
            while current != start:
                current = forward_parent[current]
                path.append(current)
            return path[::-1]
        if bfs(backward_queue, backward_visited, backward_parent):
            path = [start]
            current = start
            while current != goal:
                current = backward_parent[current]
                path.append(current)
