from collections import deque

def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        return []

    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Bidirectional BFS
    forward_visited = {(start_row, start_col): [start]}
    backward_visited = {(goal_row, goal_col): [goal]}
    forward_queue = deque([(start_row, start_col)])
    backward_queue = deque([(goal_row, goal_col)])

    while forward_queue and backward_queue:
        # Expand forward
        if len(forward_queue) <= len(backward_queue):
            current_r, current_c = forward_queue.popleft()
            for dr, dc in directions:
                nr, nc = current_r + dr, current_c + dc
                if is_valid(nr, nc):
                    if (nr, nc) in backward_visited:
                        path = forward_visited[(current_r, current_c)] + backward_visited[(nr, nc)][::-1]
                        return path
                    if (nr, nc) not in forward_visited:
                        forward_visited[(nr, nc)] = forward_visited[(current_r, current_c)] + [(nr, nc)]
                        forward_queue.append((nr, nc))
        else:
            current_r, current_c = backward_queue.popleft()
            for dr, dc in directions:
                nr, nc = current_r + dr, current_c + dc
                if is_valid(nr, nc):
                    if (nr, nc) in forward_visited:
                        path = backward_visited[(current_r, current_c)] + forward_visited[(nr, nc)][::-1]
