def solve(grid, start, goal):
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        return []

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(queue, visited, came_from):
        while queue:
            r, c, path = queue.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    came_from[(nr, nc)] = (r, c)
                    new_path = path + [(nr, nc)]
                    queue.append((nr, nc, new_path))
                    if (nr, nc) == goal:
                        return new_path
        return []

    if grid[start[0]][start[1]] != '.' or grid[goal[0]][goal[1]] != '.':
        return []

    visited_start = set()
    visited_goal = set()
    came_from_start = {}
    came_from_goal = {}

    queue_start = deque([(start[0], start[1], [start])])
    visited_start.add((start[0], start[1]))

    queue_goal = deque([(goal[0], goal[1], [goal])])
    visited_goal.add((goal[0], goal[1]))

    while queue_start and queue_goal:
        result = bfs(queue_start, visited_start, came_from_start)
        if result:
            return result
        result = bfs(queue_goal, visited_goal, came_from_goal)
