        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        return [(r + dr, c + dc) for dr, dc in directions
                if 0 <= r + dr < rows and 0 <= c + dc < cols
                and grid[r + dr][c + dc] == '.']

    def bfs(start, goal, direction):
