        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    def bidirectional_bfs(start, goal):
        start_queue = deque()
