def solve(grid, start, goal):
    from collections import deque

    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    # Check if start or goal is a wall or out of bounds
    if not (0 <= start_row < rows and 0 <= start_col < cols and grid[start_row][start_col] == '.'):
        return []
    if not (0 <= goal_row < rows and 0 <= goal_col < cols and grid[goal_row][goal_col] == '.'):
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(depth, current, path, visited):
        if depth == 0:
            return False
        row, col = current
        if (row, col) == goal:
            path.append(goal)
            return True
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                visited.add((nr, nc))
                path.append((nr, nc))
                if dfs(depth - 1, (nr, nc), path, visited):
                    return True
                path.pop()
                visited.remove((nr, nc))
        return False

    # Iterative Deepening DFS
    max_depth = rows * cols  # Maximum possible depth
    for depth in range(1, max_depth + 1):
        path = [start]
        visited = {start}
        if dfs(depth, start, path, visited):
            return path
    return []
