    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or \
       not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(pos):
        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def dfs(r, c, depth, path, visited):
        if depth == 0:
            return False
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if (nr, nc) not in visited and is_valid((nr, nc)):
                visited.add((nr, nc))
                path.append((nr, nc))
                if (nr, nc) == goal:
                    return True
                if dfs(nr, nc, depth - 1, path, visited):
                    return True
                path.pop()
                visited.remove((nr, nc))
        return False

    max_depth = len(grid) * len(grid[0])
    visited = set()
    visited.add(start)
    path = [start]
    for depth in range(1, max_depth + 1):
        if dfs(start[0], start[1], depth, path, visited):
            return path
    return []
