        if len(path) > max_depth:
            return False
        r, c = current
        if (r, c) == goal:
            return True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                path.append((nr, nc))
                if dfs((nr, nc), path, max_depth):
                    return True
                path.pop()
        return False

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []
    if start == goal:
        return [start]

    max_depth = 0
    path = [start]
    while True:
        if dfs(start, path, max_depth):
            return path
        max_depth += 1
        if max_depth > rows * cols:
            return []
