    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if not (0 <= start_row < rows and 0 <= start_col < cols):
        return []
    if not (0 <= goal_row < rows and 0 <= goal_col < cols):
        return []
    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []
    if start == goal:
        return [start]

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def dfs_depth(current, path, depth, max_depth):
        if depth > max_depth:
            return False
        r, c = current
        if current == goal:
            path.append(current)
            return True
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_free(nr, nc) and (nr, nc) not in path:
                path.append((nr, nc))
                if dfs_depth((nr, nc), path, depth + 1, max_depth):
                    return True
                path.pop()
        return False

    max_depth = 0
    path = [start]
    while True:
        if dfs_depth(start, path, 0, max_depth):
            return path
        max_depth += 1
        if max_depth > rows * cols:
            return []

