def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal is a wall or out of bounds
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(depth, current, path, visited):
        if depth == 0:
            return False
        row, col = current
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                visited.add((nr, nc))
                path.append((nr, nc))
                if (nr, nc) == goal:
                    return True
                if dfs(depth - 1, (nr, nc), path, visited):
                    return True
                path.pop()
                visited.remove((nr, nc))
        return False

    max_depth = rows * cols  # Maximum possible depth in a grid
    for depth in range(1, max_depth + 1):
        visited = {start}
        path = [start]
        if dfs(depth, start, path, visited):
            return path
    return []
