def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def dfs(current, path, depth_limit):
        if current == goal:
            return path.copy()
        if depth_limit <= 0:
            return None
        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if is_valid(r, c) and (r, c) not in path:
                path.append((r, c))
                result = dfs((r, c), path, depth_limit - 1)
                if result is not None:
                    return result
                path.pop()
        return None

    max_depth = 2 * max(len(grid), len(grid[0])) + 1
    for depth in range(1, max_depth + 1):
        path = [start]
        result = dfs(start, path, depth)
        if result is not None:
            return result
    return []
