import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    priority_queue = [(0, start)]
    came_from = {}
    g_score = {start: 0}

    while priority_queue:
        _, current = heapq.heappop(priority_queue)
        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            path.reverse()
            return path

        if current in visited:
            continue
        visited.add(current)

        r, c = current
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                tentative_gscore = g_score[current] + 1
                if (nr, nc) not in g_score or tentative_gscore < g_score[(nr, nc)]:
                    came_from[(nr, nc)] = current
                    g_score[(nr, nc)] = tentative_gscore
                    heapq.heappush(priority_queue, (tentative_gscore, (nr, nc)))

    return []
