        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(node, goal):
        return abs(node[0] - goal[0]) + abs(node[1] - goal[1])

    priority_queue = [(heuristic(start, goal), 0, start)]
    visited = set()
    parent = {}

    while priority_queue:
        _, cost, current = heapq.heappop(priority_queue)
