import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        # Check if start and goal are within grid bounds and are free
        if (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
            if grid[start[0]][start[1]] == '.' and grid[goal[0]][goal[1]] == '.':
                return [start]
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue for A* search
    heap = []
    heapq.heappush(heap, (0, start))
    came_from = {}
    g_cost = {start: 0}
    f_cost = {start: heuristic(start, goal)}

    while heap:
        _, current = heapq.heappop(heap)
        if current == goal:
            # Reconstruct path
            path = [current]
            while current != start:
                current = came_from[current]
                path.append(current)
            return path[::-1]

        for dr, dc in directions:
            r, c = current[0] + dr, current[1] + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.':
                neighbor = (r, c)
                tentative_g = g_cost[current] + 1
                if neighbor not in g_cost or tentative_g < g_cost[neighbor]:
                    came_from[neighbor] = current
                    g_cost[neighbor] = tentative_g
                    f_cost[neighbor] = tentative_g + heuristic(neighbor, goal)
                    heapq.heappush(heap, (f_cost[neighbor], neighbor))

    # No path found
    return []

def heuristic(pos, goal):
    return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])
