import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal is out of bounds or a wall
    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue for Dijkstra's algorithm (using tuple (cost, row, col))
    heap = [(0, start[0], start[1])]
    # Keep track of visited cells and their cost
    visited = {}

    while heap:
        cost, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            # Reconstruct path
            path = []
            current = (r, c)
            while current in visited:
                path.append(current)
                current = visited[current]
            path.append(start)
            return path[::-1]
        if (r, c) in visited:
            continue
        visited[(r, c)] = (cost, (r - directions[0][0], c - directions[0][1])) if directions[0] == (r - directions[0][0], c - directions[0][1]) else (cost, (r - directions[1][0], c - directions[1][1])) if directions[1] == (r - directions[1][0], c - directions[1][1]) else (cost, (r - directions[2][0], c - directions[2][1])) if directions[2] == (r - directions[2][0], c - directions[2][1]) else (cost, (r - directions[3][0], c - directions[3][1]))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                if (nr, nc) not in visited or cost + 1 < visited[(nr, nc)][0]:
                    visited[(nr, nc)] = (cost + 1, (r, c))
                    heapq.heappush(heap, (cost + 1, nr, nc))

    # No path found
    return []

