import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        # Check if the start is a free cell
        if 0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Dijkstra's algorithm using a priority queue
    heap = [(0, start[0], start[1])]
    visited = set()
    parent = {}

    while heap:
        _, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            # Reconstruct path
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = parent[(r, c)]
            path.append(start)
            return path[::-1]

        if (r, c) in visited:
            continue
        visited.add((r, c))

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                heapq.heappush(heap, (1, nr, nc))
                parent[(nr, nc)] = (r, c)

    return []
