import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if (
        start_row < 0 or start_row >= rows or
        start_col < 0 or start_col >= cols or
        grid[start_row][start_col] == '#' or
        grid[goal_row][goal_col] == '#'
    ):
        return []

    if start == goal:
        return [start]

    visited = set()
    pq = [(0, start_row, start_col)]
    parent = {}

    while pq:
        _, r, c = heapq.heappop(pq)
        if (r, c) == (goal_row, goal_col):
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in visited:
                heapq.heappush(pq, (1, nr, nc))
                parent[(nr, nc)] = (r, c)

    if (goal_row, goal_col) not in parent:
        return []

    path = []
    current = (goal_row, goal_col)
    while current:
        path.append(current)
        current = parent.get(current)
    return path[::-1]
