from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Initialize distance array with infinity
    dist = [float('inf')] * n
    dist[s] = 0

    # Queue for SPFA (Shortest Path Faster Algorithm)
    queue = deque([s])
    in_queue = [False] * n
    in_queue[s] = True
    cnt = [0] * n  # Count of relaxations per node

    while queue:
        u = queue.popleft()
        in_queue[u] = False
        for u_, v_, w in edges:
            if u_ == u:
                if dist[v_] > dist[u_] + w:
                    dist[v_] = dist[u_] + w
                    if not in_queue[v_]:
                        queue.append(v_)
                        in_queue[v_] = True
                        cnt[v_] += 1
                        if cnt[v_] > n:
                            return -1  # Negative cycle detected

    return dist[t] if dist[t] != float('inf') else -1

