    buckets[0].append(s)

    while buckets:
        # Find the bucket with the smallest distance
        for d in range(len(buckets)):
            if buckets[d]:
                break
        else:
            break  # No more nodes to process

        # Process all nodes in the current bucket
        for u in buckets[d]:
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    # Move v to the bucket corresponding to its new distance
                    buckets[dist[v]].append(v)

        # Clear the current bucket
        buckets[d].clear()

    return dist[t] if dist[t] != float('inf') else -1

