from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Bidirectional BFS
    visited_start = set()
    visited_goal = set()
    queue_start = deque()
    queue_goal = deque()

    queue_start.append((start[0], start[1], [start]))
    visited_start.add((start[0], start[1]))
    queue_goal.append((goal[0], goal[1], [goal]))
    visited_goal.add((goal[0], goal[1]))

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue_start and queue_goal:
        # Expand from start
        for _ in range(len(queue_start)):
            r, c, path = queue_start.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited_start:
                    if (nr, nc) in visited_goal:
                        return path + [tuple(visited_goal[(nr, nc)])]
                    visited_start.add((nr, nc))
                    queue_start.append((nr, nc, path + [(nr, nc)]))

        # Expand from goal
        for _ in range(len(queue_goal)):
            r, c, path = queue_goal.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited_goal:
                    if (nr, nc) in visited_start:
                        return path + [tuple(visited_start[(nr, nc)])]
                    visited_goal.add((nr, nc))
                    queue_goal.append((nr, nc, path + [(nr, nc)]))

    return []
