from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(from_pos, target_pos):
        visited = set()
        queue = deque([(from_pos, [from_pos])])
        visited.add(from_pos)
        while queue:
            pos, path = queue.popleft()
            if pos == target_pos:
                return path
            for dr, dc in directions:
                r, c = pos[0] + dr, pos[1] + dc
                if is_valid(r, c) and (r, c) not in visited:
                    visited.add((r, c))
                    queue.append(((r, c), path + [(r, c)]))
        return []

    forward = bfs(start, goal)
    backward = bfs(goal, start)

    if not forward or not backward:
        return []

    # Find the intersection point
    forward_set = set(forward)
    for point in backward:
        if point in forward_set:
            return forward[:forward.index(point)] + backward[backward.index(point):][::-1]
    return []
