from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(queue, visited, parent):
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = (r, c)
                    queue.append((nr, nc))
                    if (nr, nc) == goal:
                        return True
        return False

    forward_queue = deque([start])
    forward_visited = {start}
    forward_parent = {}

    backward_queue = deque([goal])
    backward_visited = {goal}
    backward_parent = {}

    while forward_queue and backward_queue:
        if bfs(forward_queue, forward_visited, forward_parent):
            path = []
            current = goal
            while current != start:
                path.append(current)
                current = forward_parent[current]
            path.append(start)
            return path[::-1]
        if bfs(backward_queue, backward_visited, backward_parent):
            path = []
            current = start
            while current != goal:
                path.append(current)
                current = backward_parent[current]
            path.append(goal)
            return path

    return []
