from collections import deque

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    # Bidirectional BFS
    forward_visited = {start: [start]}
    backward_visited = {goal: [goal]}
    forward_queue = deque([start])
    backward_queue = deque([goal])

    while forward_queue and backward_queue:
        # Expand forward direction
        if forward_queue:
            current = forward_queue.popleft()
            for neighbor in get_neighbors(*current):
                if neighbor not in forward_visited:
                    forward_visited[neighbor] = forward_visited[current] + [neighbor]
                    forward_queue.append(neighbor)
                    if neighbor in backward_visited:
                        return forward_visited[neighbor] + backward_visited[neighbor][::-1][1:]

        # Expand backward direction
        if backward_queue:
            current = backward_queue.popleft()
            for neighbor in get_neighbors(*current):
                if neighbor not in backward_visited:
                    backward_visited[neighbor] = backward_visited[current] + [neighbor]
                    backward_queue.append(neighbor)
                    if neighbor in forward_visited:
                        return forward_visited[neighbor] + backward_visited[neighbor][::-1][1:]

    return []
