    def bfs(start, goal, frontier, visited, came_from):
        while frontier:
            r, c = frontier.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    came_from[(nr, nc)] = (r, c)
                    if (nr, nc) == goal:
                        return True
                    frontier.append((nr, nc))
        return False

    start_frontier = deque([start])
    start_visited = {start}
    start_came_from = {}

    goal_frontier = deque([goal])
    goal_visited = {goal}
    goal_came_from = {}

    while start_frontier and goal_frontier:
        if bfs(start, goal, start_frontier, start_visited, start_came_from):
            path = []
            current = goal
            while current != start:
                path.append(current)
                current = start_came_from[current]
            path.append(start)
            return path[::-1]
