def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        return []
    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def bfs(start, goal, visited, other_visited):
        queue = deque([(start, [start])])
        visited.add(start)
        directions = [(-1,0), (1,0), (0,-1), (0,1)]
        while queue:
            (r, c), path = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc):
                    if (nr, nc) in other_visited:
                        return path + [(nr, nc)]
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append(((nr, nc), path + [(nr, nc)]))
        return []

    forward_visited = set()
    backward_visited = set()
    forward_queue = deque([start])
    backward_queue = deque([goal])
    forward_visited.add(start)
    backward_visited.add(goal)

    while forward_queue and backward_queue:
        forward_path = bfs(start, goal, forward_visited, backward_visited)
        if forward_path:
            return forward_path
        backward_path = bfs(goal, start, backward_visited, forward_visited)
        if backward_path:
            return backward_path + backward_path[:-1][::-1]

    return []
