from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) or
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    forward = {start: [start]}
    backward = {goal: [goal]}
    forward_set = {start}
    backward_set = {goal}
    visited = set()
    visited.add(start)
    visited.add(goal)

    while forward_set and backward_set:
        if len(forward) > len(backward):
            forward, backward = backward, forward
            forward_set, backward_set = backward_set, forward_set

        next_forward = {}
        for node in forward:
            for neighbor in get_neighbors(*node):
                if neighbor not in visited:
                    path = forward[node] + [neighbor]
                    next_forward[neighbor] = path
                    visited.add(neighbor)
                    if neighbor in backward_set:
                        return path + backward[neighbor][::-1]
        forward_set = set(next_forward.keys())
        forward.update(next_forward)

    return []
