    if not grid or start == goal:
        if is_free(grid, start):
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    if not is_free(grid, start) or not is_free(grid, goal):
        return []

    visited = [[False for _ in range(cols)] for _ in range(rows)]
    parent = [[None for _ in range(cols)] for _ in range(rows)]

    queue = deque()
    queue.append(start)
    visited[start[0]][start[1]] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and is_free(grid, (nr, nc)):
                visited[nr][nc] = True
                parent[nr][nc] = (r, c)
                queue.append((nr, nc))
                if (nr, nc) == goal:
                    queue.clear()
                    break

    if not visited[goal[0]][goal[1]]:
        return []

    path = []
