import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list for original graph and reversed graph
    graph = [[] for _ in range(n)]
    reversed_graph = [[] for _ in range(n)]

    for u, v, w in edges:
        graph[u].append((v, w))
        reversed_graph[v].append((u, w))

    # Dijkstra's algorithm
    def dijkstra(start, graph, n):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = [False] * n

        while heap:
            d, u = heapq.heappop(heap)
            if visited[u]:
                continue
            visited[u] = True
            for v, w in graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_from_s = dijkstra(s, graph, n)
    dist_from_t = dijkstra(t, reversed_graph, n)

    # Check if t is reachable from s
    if dist_from_s[t] == float('inf'):
        return -1

    # If the first run from s already reached t
    if dist_from_s[t] < float('inf'):
        return dist_from_s[t]

    # Bidirectional search
    from collections import deque

    # Helper to perform BFS with distance tracking
    def bfs(start, graph, dist, visited):
        queue = deque()
        queue.append((start, 0))
        visited[start] = True
        while queue:
            u, d = queue.popleft()
            for v, w in graph[u]:
                if not visited[v]:
                    dist[v] = d + w
                    visited[v] = True
                    queue.append((v, dist[v]))
                    if v == t:
                        return dist[v]
        return float('inf')

    # Bidirectional BFS
    visited_s = [False] * n
    visited_t = [False] * n
    dist_s = [float('inf')] * n
    dist_t = [float('inf')] * n
    dist_s[s] = 0
    dist_t[t] = 0

    while True:
        # Forward from s
        if bfs(s, graph, dist_s, visited_s) != float('inf'):
            if dist_s[t] != float('inf'):
                return dist_s[t]
        # Backward from t on reversed graph
        if bfs(t, reversed_graph, dist_t, visited_t) != float('inf'):
            if dist_t[s] != float('inf'):
                return dist_t[s]
        # Check if overlap
        for i in range(n):
            if visited_s[i] and visited_t[i]:
                # If the path from s to i and from t to i overlap
                return dist_s[i] + dist_t[i]
    return -1
