def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list for the original graph
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Build adjacency list for the reversed graph
    rev_adj = [[] for _ in range(n)]
    for u, v, w in edges:
        rev_adj[v].append((u, w))

    # Dijkstra's algorithm
    def dijkstra(graph, start, target):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if u == target:
                return d
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Bidirectional Dijkstra
    dist_s = [float('inf')] * n
    dist_t = [float('inf')] * n
    dist_s[s] = 0
    dist_t[t] = 0
    queue_s = [(0, s)]
    queue_t = [(0, t)]

    while queue_s and queue_t:
        # Expand from s
        d, u = heapq.heappop(queue_s)
        if d > dist_s[u]:
            continue
        for v, w in adj[u]:
            if dist_s[v] > d + w:
                dist_s[v] = d + w
                heapq.heappush(queue_s, (dist_s[v], v))
        if dist_s[t] < float('inf'):
            return dist_s[t]

        # Expand from t on reversed graph
        d, u = heapq.heappop(queue_t)
        if d > dist_t[u]:
            continue
        for v, w in rev_adj[u]:
            if dist_t[v] > d + w:
                dist_t[v] = d + w
                heapq.heappush(queue_t, (dist_t[v], v))
        if dist_t[s] < float('inf'):
            return dist_t[s]

    return -1
