    visited = [False] * n
    visited[s] = True
    visited[t] = True
    from_s = [float('inf')] * n
    from_s[s] = 0
    from_t = [float('inf')] * n
    from_t[t] = 0

    while True:
        # Forward from s
        for v, w in adj[s]:
            if from_s[v] > from_s[s] + w:
                from_s[v] = from_s[s] + w
        # Backward from t (on reversed graph)
        for v, w in rev_adj[t]:
