    dist_from_s = dijkstra(s, graph, n)
    dist_from_t = dijkstra(t, reversed_graph, n)

    # Check if t is reachable from s
    if dist_from_s[t] == float('inf'):
        return -1

    # Check if s is reachable from t in reversed graph (i.e., t is reachable from s in original graph)
    if dist_from_t[s] == float('inf'):
        return -1

