    forward_dist = dijkstra(s, graph, n)
    backward_dist = dijkstra(t, reversed_graph, n)

    # Alternate between forward and backward Dijkstra
    while True:
        # Forward search from s
        new_forward_dist = dijkstra(s, graph, n)
        for i in range(n):
            if new_forward_dist[i] < forward_dist[i]:
                forward_dist[i] = new_forward_dist[i]
        # Backward search from t on reversed graph
