                backward_dist[i] = new_backward_dist[i]

        # Check for meeting point
        for i in range(n):
            if forward_dist[i] + backward_dist[i] < float('inf'):
                return forward_dist[i] + backward_dist[i]

        # If no meeting point found, return -1 (though this shouldn't happen if s and t are connected)
