    def build_reversed_graph():
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[v].append((u, w))
        return graph

    # Dijkstra's algorithm
    def dijkstra(graph, start, target):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            if u == target:
                return current_dist
            for v, w in graph[u]:
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Bidirectional Dijkstra
    original_graph = build_graph()
    reversed_graph = build_reversed_graph()

    dist_forward = [float('inf')] * n
    dist_backward = [float('inf')] * n
    dist_forward[s] = 0
    dist_backward[t] = 0

    def get_neighbors(graph, node):
        return graph[node]

    # Initialize priority queues
    forward_heap = [(0, s)]
    backward_heap = [(0, t)]
    visited_forward = {s}
    visited_backward = {t}

    while forward_heap and backward_heap:
        # Expand forward
        while forward_heap:
            d, u = heapq.heappop(forward_heap)
            if u in visited_forward:
                continue
            visited_forward.add(u)
            if u in visited_backward:
                return d + dist_backward[u]
            for v, w in get_neighbors(original_graph, u):
                if dist_forward[v] > d + w:
                    dist_forward[v] = d + w
                    heapq.heappush(forward_heap, (dist_forward[v], v))

        # Expand backward
        while backward_heap:
            d, u = heapq.heappop(backward_heap)
            if u in visited_backward:
