    # Build adjacency list for original graph
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Build adjacency list for reversed graph
    reversed_graph = [[] for _ in range(n)]
    for u, v, w in edges:
        reversed_graph[v].append((u, w))

    # Dijkstra's algorithm with priority queue
    def dijkstra(start, graph):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            for v, w in graph[u]:
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_forward = dijkstra(s, graph)
    dist_backward = dijkstra(t, reversed_graph)

    # Check if t is reachable from s
    if dist_forward[t] == float('inf'):
        return -1

    # Run bidirectional Dijkstra alternately
    forward = {s: 0}
    backward = {t: 0}
    forward_nodes = {s}
    backward_nodes = {t}

    while forward_nodes and backward_nodes:
        # Forward search
        min_dist = float('inf')
        next_node = -1
        for u in forward_nodes:
            for v, w in graph[u]:
                if v not in forward:
                    if forward[u] + w < min_dist:
                        min_dist = forward[u] + w
                        next_node = v
        if next_node != -1:
            forward[next_node] = min_dist
            forward_nodes.add(next_node)

        # Backward search on reversed graph
        min_dist = float('inf')
        next_node = -1
        for u in backward_nodes:
            for v, w in reversed_graph[u]:
                if v not in backward:
                    if backward[u] + w < min_dist:
                        min_dist = backward[u] + w
                        next_node = v
        if next_node != -1:
            backward[next_node] = min_dist
            backward_nodes.add(next_node)

        # Check for intersection
        if forward_nodes & backward_nodes:
            for node in forward_nodes & backward_nodes:
                if node in forward and node in backward:
                    return forward[node] + backward[node]

    # If no path found
    return -1
