        return 0

    # Build adjacency list for original graph
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Build adjacency list for reversed graph
    reversed_graph = [[] for _ in range(n)]
    for u, v, w in edges:
        reversed_graph[v].append((u, w))

    # Dijkstra's algorithm
    def dijkstra(graph, start, target):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            if u == target:
                return current_dist
            for v, w in graph[u]:
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Bidirectional Dijkstra
    dist_from_s = [float('inf')] * n
    dist_from_t = [float('inf')] * n
    dist_from_s[s] = 0
    dist_from_t[t] = 0
    queue_s = [(0, s)]
    queue_t = [(0, t)]
    visited_s = set()
    visited_t = set()

    while queue_s and queue_t:
        # Run Dijkstra from s
        while queue_s:
            current_dist, u = heapq.heappop(queue_s)
            if u in visited_s:
                continue
            visited_s.add(u)
            if u in visited_t:
