def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Initialize bucket queue
    import heapq

    # bucket_queue is a list of lists, bucket_queue[d] contains nodes with distance d
    # max_distance is an upper bound on possible distances
    max_distance = 100 * 100  # since each edge weight is at most 100 and n <= 100
    bucket_queue = [[] for _ in range(max_distance + 1)]
    distance = [-1] * n
    distance[s] = 0
    bucket_queue[0].append(s)

    while True:
        # Find the first non-empty bucket
        d = 0
        while d <= max_distance and not bucket_queue[d]:
            d += 1
        if d > max_distance:
            break  # no more nodes to process

        # Process all nodes in bucket d
        for u in bucket_queue[d]:
            for v, w in graph[u]:
                if distance[v] == -1 or distance[v] > distance[u] + w:
                    if distance[v] == -1:
                        distance[v] = distance[u] + w
                        bucket_queue[distance[v]].append(v)
                    else:
                        # Update the distance and add to the new bucket
                        new_dist = distance[u] + w
                        if new_dist < distance[v]:
                            distance[v] = new_dist
                            bucket_queue[new_dist].append(v)
        # Clear the current bucket
        bucket_queue[d] = []

