import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list for original graph and reversed graph
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        rev_adj[v].append((u, w))

    # Dijkstra's algorithm with priority queue
    def dijkstra(start, adj):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()
        while heap:
            d, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_from_s = dijkstra(s, adj)
    dist_from_t = dijkstra(t, rev_adj)

    # Check if there is a path
    if dist_from_s[t] == float('inf'):
        return -1

    # Early stopping with bidirectional search
    # We'll alternate between forward and backward searches
    visited_forward = set()
    visited_backward = set()
    forward_heap = [(0, s)]
    backward_heap = [(0, t)]
    forward_dist = {s: 0}
    backward_dist = {t: 0}

    while forward_heap and backward_heap:
        # Forward search
        d, u = heapq.heappop(forward_heap)
        if u in visited_forward:
            continue
        visited_forward.add(u)
        for v, w in adj[u]:
            if v not in visited_forward:
                new_dist = d + w
                if v not in forward_dist or new_dist < forward_dist[v]:
                    forward_dist[v] = new_dist
                    heapq.heappush(forward_heap, (new_dist, v))
        if u in visited_backward:
            return d + backward_dist[u]

        # Backward search on reversed graph
        d_rev, u_rev = heapq.heappop(backward_heap)
        if u_rev in visited_backward:
            continue
        visited_backward.add(u_rev)
        for v_rev, w_rev in rev_adj[u_rev]:
            if v_rev not in visited_backward:
                new_dist_rev = d_rev + w_rev
                if v_rev not in backward_dist or new_dist_rev < backward_dist[v_rev]:
                    backward_dist[v_rev] = new_dist_rev
                    heapq.heappush(backward_heap, (new_dist_rev, v_rev))
        if u_rev in visited_forward:
            return d_rev + forward_dist[u_rev]

    return -1
