    rev_adj = [[] for _ in range(n)]
    for u, v, w in edges:
        rev_adj[v].append((u, w))

    # Dijkstra's algorithm
    def dijkstra(start, adj, n):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()
        while heap:
            d, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_s = dijkstra(s, adj, n)
    dist_t = dijkstra(t, rev_adj, n)

    # Check if there's a path
    if dist_s[t] == float('inf'):
        return -1

    # Now perform bidirectional search alternating between forward and backward
    # Start with forward from s
    forward_dist = {s: 0}
    backward_dist = {t: 0}
    visited_forward = {s}
    visited_backward = {t}
