        # Forward step
        d, u = heapq.heappop(forward_heap)
        if u in visited_backward:
            return d + backward_dist[u]
        for v, w in adj[u]:
            if v not in visited_forward:
                visited_forward.add(v)
                forward_dist[v] = d + w
                heapq.heappush(forward_heap, (forward_dist[v], v))

        # Backward step
