    reversed_graph = [[] for _ in range(n)]
    for u, v, w in edges:
        reversed_graph[v].append((u, w))

    # Dijkstra's algorithm
    def dijkstra(start, graph, n):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            current_dist, u = heapq.heappop(heap)
            if current_dist > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_from_s = dijkstra(s, graph, n)
    dist_from_t = dijkstra(t, reversed_graph, n)

    # Check if t is reachable from s
    if dist_from_s[t] == float('inf'):
        return -1

    # Initialize for bidirectional search
    forward_dist = dijkstra(s, graph, n)
    backward_dist = dijkstra(t, reversed_graph, n)

    # Set of visited nodes
    visited = [False] * n
    forward_heap = [(forward_dist[i], i) for i in range(n)]
    backward_heap = [(backward_dist[i], i) for i in range(n)]

    heapq.heapify(forward_heap)
    heapq.heapify(backward_heap)

    # Set visited for forward and backward
    while forward_heap and backward_heap:
        # Expand forward
        while forward_heap:
            d, u = heapq.heappop(forward_heap)
            if visited[u]:
                continue
            visited[u] = True
            if u in [i for d, i in backward_heap]:
                # Check if the node was already visited in the backward search
                for i in range(len(backward_heap)):
                    if backward_heap[i][1] == u:
                        return d + backward_heap[i][0]
            for v, w in graph[u]:
                if not visited[v]:
                    new_dist = d + w
                    if new_dist < forward_dist[v]:
                        forward_dist[v] = new_dist
                        heapq.heappush(forward_heap, (new_dist, v))
            if visited[t]:
                break

        # Expand backward
