def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list for original graph
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Build reversed adjacency list for backward search
    reversed_graph = [[] for _ in range(n)]
    for u, v, w in edges:
        reversed_graph[v].append((u, w))

    # Dijkstra's algorithm
    def dijkstra(start, graph, reverse=False):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            for v, w in graph[u]:
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_from_s = dijkstra(s, graph)
    dist_from_t = dijkstra(t, reversed_graph, reverse=True)

    # Check if t is reachable from s
    if dist_from_s[t] == float('inf'):
        return -1

    # If we already have the shortest path from s to t
    if dist_from_s[t] < float('inf'):
        return dist_from_s[t]

    # If we have the shortest path from t to s in reversed graph, it is the same
    if dist_from_t[s] == float('inf'):
        return -1

    # Now perform bidirectional search alternately
    # Rebuild the graphs again to avoid modifying original ones
    graph_forward = [[] for _ in range(n)]
    for u, v, w in edges:
        graph_forward[u].append((v, w))

    graph_backward = [[] for _ in range(n)]
    for u, v, w in edges:
        graph_backward[v].append((u, w))

    # Priority queues for forward and backward searches
    forward_heap = [(0, s)]
    backward_heap = [(0, t)]

    # Visited sets for forward and backward searches
    forward_visited = {s: 0}
    backward_visited = {t: 0}

    # Keep track of the shortest path found
    min_dist = float('inf')

    while forward_heap and backward_heap:
        # Process forward search
        current_dist, u = heapq.heappop(forward_heap)
        if u in backward_visited:
            min_dist = min(min_dist, current_dist + backward_visited[u])
            break
        if u in forward_visited and current_dist > forward_visited[u]:
            continue
        forward_visited[u] = current_dist
        for v, w in graph_forward[u]:
            if v not in forward_visited or current_dist + w < forward_visited[v]:
                heapq.heappush(forward_heap, (current_dist + w, v))

        # Process backward search
        current_dist_rev, u_rev = heapq.heappop(backward_heap)
        if u_rev in forward_visited:
            min_dist = min(min_dist, current_dist_rev + forward_visited[u_rev])
