import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list for the original graph
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Build adjacency list for the reversed graph
    rev_adj = [[] for _ in range(n)]
    for u, v, w in edges:
        rev_adj[v].append((u, w))

    # Dijkstra's algorithm
    def dijkstra(start, adj, n):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_from_s = dijkstra(s, adj, n)
    dist_from_t = dijkstra(t, rev_adj, n)

    # Check if t is reachable from s
    if dist_from_s[t] == float('inf'):
        return -1

    # Now perform bidirectional Dijkstra
    forward = {s: 0}
    backward = {t: 0}
    visited_forward = {s}
    visited_backward = {t}
    heap_forward = [(0, s)]
    heap_backward = [(0, t)]

    while heap_forward and heap_backward:
        # Expand forward
        d, u = heapq.heappop(heap_forward)
        if u in visited_backward:
            return d + backward[u]
        for v, w in adj[u]:
            if v not in visited_forward:
                visited_forward.add(v)
                forward[v] = d + w
                heapq.heappush(heap_forward, (forward[v], v))

        # Expand backward
        d, u = heapq.heappop(heap_backward)
        if u in visited_forward:
            return d + forward[u]
        for v, w in rev_adj[u]:
            if v not in visited_backward:
                visited_backward.add(v)
                backward[v] = d + w
                heapq.heappush(heap_backward, (backward[v], v))

