    if s == t:
        return 0

    # Build adjacency list for original graph
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Build adjacency list for reversed graph
    reversed_graph = [[] for _ in range(n)]
    for u, v, w in edges:
        reversed_graph[v].append((u, w))

    # Dijkstra's algorithm
    def dijkstra(start, graph, n):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            for v, w in graph[u]:
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_from_s = dijkstra(s, graph, n)
    dist_from_t = dijkstra(t, reversed_graph, n)

    # Check if there is a path
    if dist_from_s[t] == float('inf'):
        return -1

    # Initialize frontiers
    frontier_s = [(0, s)]
    frontier_t = [(0, t)]
    visited_s = {s}
    visited_t = {t}
    found = False
    result = float('inf')

    while frontier_s and frontier_t:
        # Expand from s
        if not found:
            current_dist, u = heapq.heappop(frontier_s)
            for v, w in graph[u]:
                if v not in visited_s:
                    visited_s.add(v)
                    heapq.heappush(frontier_s, (current_dist + w, v))
                    if v in visited_t:
                        result = min(result, current_dist + w + dist_from_t[v])
                        found = True
                        break
        # Expand from t
        if not found:
            current_dist, u = heapq.heappop(frontier_t)
            for v, w in reversed_graph[u]:
                if v not in visited_t:
                    visited_t.add(v)
